insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-set-up-home-internet-in-dubai', 'How do I set up home internet in Dubai?', '<p>Etisalat or du after Ejari — choose fiber plan. Not included in agency fees; arrange post handover.</p>', 'How do I set up home internet in Dubai?', 117, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-chiller-included-in-rent', 'Is chiller included in rent?', '<p>Listing-specific. Some landlords include capped chiller; others bill tenant directly. Check listing or <a href="/account/transactions">property applications</a> contract.</p>', 'Is chiller included in rent?', 118, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-to-ejari-when-i-move-out', 'What happens to Ejari when I move out?', '<p>Cancel Ejari after final DEWA bill and deposit return. Agent advises on notice period per <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'What happens to Ejari when I move out?', 119, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-short-term-rentals-need-ejari', 'Do short-term rentals need Ejari?', '<p>Holiday lets under DTCM holiday home rules may differ from long-term Ejari. <a href="/pages/contact">contact our team</a> for your rental type.</p>', 'Do short-term rentals need Ejari?', 120, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-ejari-be-done-without-an-agent', 'Can Ejari be done without an agent?', '<p>Yes via Dubai REST app, but agencies typically handle it for accuracy. Included in our <a href="/pages/how-it-works">How It Works</a> service.</p>', 'Can Ejari be done without an agent?', 121, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-documents-does-ejari-require', 'What documents does Ejari require?', '<p>Signed tenancy contract, landlord title deed copy, tenant passport/Emirates ID, DEWA premise number. Prepare via <a href="/account/profile">My Profile</a>.</p>', 'What documents does Ejari require?', 122, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-update-ejari-for-contract-renewal', 'How do I update Ejari for contract renewal?', '<p>Renew through Ejari system with new contract dates — agent handles on renewal in <a href="/account/transactions">property applications</a>.</p>', 'How do I update Ejari for contract renewal?', 123, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-can-i-learn-more-about-move-in-utilities', 'Where can I learn more about move-in utilities?', '<p><a href="/pages/shipping">Handover Information</a> and <a href="/pages/renting-guide">Renting Guide</a> cover DEWA, Ejari, and key collection in detail.</p>', 'Where can I learn more about move-in utilities?', 124, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-is-handover-scheduled-after-payment', 'When is handover scheduled after payment?', '<p>Agent schedules once payment is confirmed — typically within days for rentals, per SPA for sales. Track in <a href="/account/transactions">property applications</a>.</p>', 'When is handover scheduled after payment?', 125, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-should-i-inspect-at-handover', 'What should I inspect at handover?', '<p>Fixtures, appliances, AC, plumbing, meters readings, and community access cards. Report issues within 48 hours per <a href="/pages/shipping">Handover Information</a>.</p>', 'What should I inspect at handover?', 126, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'who-attends-the-handover-meeting', 'Who attends the handover meeting?', '<p>Tenant/buyer, agent, sometimes landlord or building manager. Details in handover notification via <a href="/account">My Account</a>.</p>', 'Who attends the handover meeting?', 127, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-documents-do-i-bring-on-handover-day', 'What documents do I bring on handover day?', '<p>Emirates ID/passport, paid invoice proof, signed contract copy, and cheques if not yet collected. List in <a href="/pages/shipping">Handover Information</a>.</p>', 'What documents do I bring on handover day?', 128, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-get-building-access-cards-and-parking', 'How do I get building access cards and parking?', '<p>Issued at handover or from building management — agent coordinates. Notes appear in <a href="/account/transactions">property applications</a> handover section.</p>', 'How do I get building access cards and parking?', 129, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-handover-checklist', 'What is a handover checklist?', '<p>Itemised list of keys, remotes, meter readings, and condition notes. Available for tenants post lease activation in tenant portal.</p>', 'What is a handover checklist?', 130, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-handover-be-done-remotely', 'Can handover be done remotely?', '<p>Power of attorney or authorized representative possible with notarized documents. <a href="/pages/contact">contact our team</a> to arrange.</p>', 'Can handover be done remotely?', 131, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-if-defects-are-found-at-handover', 'What if defects are found at handover?', '<p>Document with photos; landlord/developer fixes per contract. Snagging applies to new builds — <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'What if defects are found at handover?', 132, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-do-i-receive-keys', 'When do I receive keys?', '<p>After payment clearance, Ejari (rentals), and signed handover protocol. <a href="/pages/shipping">Handover Information</a> explains timing.</p>', 'When do I receive keys?', 133, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-is-move-in-date-communicated', 'How is move-in date communicated?', '<p>Email and <a href="/account">My Account</a> notification with date, time, location, and agent contact.</p>', 'How is move-in date communicated?', 134, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-about-furniture-delivery-after-handover', 'What about furniture delivery after handover?', '<p>Coordinate with building rules for elevator booking and working hours. Common in Marina/Downtown towers.</p>', 'What about furniture delivery after handover?', 135, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-professional-cleaning-required-before-move-in', 'Is professional cleaning required before move-in?', '<p>Contract may require professional clean — verify in lease. Standard in premium <a href="/collection/rentals">holiday and long-term rentals</a>.</p>', 'Is professional cleaning required before move-in?', 136, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pre-book-dewa-before-handover', 'Can I pre-book DEWA before handover?', '<p>Yes once Ejari is active — align activation date with key collection per <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'Can I pre-book DEWA before handover?', 137, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-after-handover-is-marked-complete', 'What happens after handover is marked complete?', '<p>Transaction status becomes Completed in <a href="/account/transactions">property applications</a>. Rentals may activate tenant portal for ongoing rent.</p>', 'What happens after handover is marked complete?', 138, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-is-the-full-handover-guide', 'Where is the full handover guide?', '<p>Read <a href="/pages/shipping">Handover Information</a> for rental and sale completion steps, plus <a href="/pages/how-it-works">How It Works</a> for the full journey.</p>', 'Where is the full handover guide?', 139, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-rental-yield-can-i-expect-in-dubai', 'What rental yield can I expect in Dubai?', '<p>Yields vary by area — often 5–8% gross for apartments, lower for premium Palm/Downtown. Compare <a href="/collection/sales">properties for sale</a> and <a href="/pages/contact">contact our team</a> for analysis.</p>', 'What rental yield can I expect in Dubai?', 140, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-dubai-property-a-good-investment-in-2026', 'Is Dubai property a good investment in 2026?', '<p>Market depends on area, supply, and visa policies. Review <a href="/collection/new">new listings</a> listings and <a href="/pages/buying-guide">Buying Guide</a> before investing.</p>', 'Is Dubai property a good investment in 2026?', 141, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
